from __future__ import annotations
from datetime import date
from ..base import Alert, IAlertChecker
from ...notification_service import SEVERITY_MAP
from ....models import Notification, DailyStockPrice
from django.contrib.auth.models import User


WHALE_WATCH_STRATEGY_NAMES = [
    'Broker Accumulation (Institutional)',
    'Smart Accumulated Crossover',
    'Ichimoku Cloud + Accumulation',
]


class WhaleWatchChecker:
    """Alerts for today's BUY/SELL signals generated by the three Whale Watch engines."""

    def check(self, user: User) -> list[Alert]:
        from ....models import SignalEpisode
        today = date.today()
        signals = SignalEpisode.objects.filter(
            start_date=today,
            direction__in=['BUY', 'SELL'],
            strategy__name__in=WHALE_WATCH_STRATEGY_NAMES,
        ).select_related('strategy')
        groups: dict[str, list] = {'BUY': [], 'SELL': []}
        for sig in signals:
            groups[sig.direction].append(sig)
        return self._build_alerts(groups)

    def _fetch_price(self, ticker: str) -> float | None:
        row = DailyStockPrice.objects.filter(ticker=ticker).order_by('-date').values('close').first()
        return float(row['close']) if row else None

    def _build_summary_text(self, signal_type: str, count: int, symbol_str: str) -> tuple[str, str]:
        if signal_type == 'BUY':
            title = f'Whale Watch: {count} Symbols Detect BUY'
            message = f'Smart money accumulation detected for {count} tickers including {symbol_str}.'
        else:
            title = f'Whale Watch: {count} Symbols Detect SELL'
            message = f'Distribution detected for {count} tickers including {symbol_str}.'
        return title, message

    def _build_alerts(self, groups: dict) -> list[Alert]:
        alerts = []
        today = date.today()
        for signal_type, sig_list in groups.items():
            if not sig_list:
                continue
            symbols = sorted({s.symbol for s in sig_list})
            n_type = (Notification.NotificationType.WHALE_BUY
                      if signal_type == 'BUY'
                      else Notification.NotificationType.WHALE_SELL)
            count = len(symbols)
            symbol_str = ', '.join(symbols[:8]) + ('...' if count > 8 else '')
            title, message = self._build_summary_text(signal_type, count, symbol_str)
            items_data = [{'symbol': s.symbol, 'detail': f"{signal_type} ({s.strategy.name})",
                           'price': self._fetch_price(s.symbol)} for s in sig_list]
            alerts.append(Alert(
                notification_type=n_type,
                title=title,
                message=message,
                ticker='SUMMARY',
                redirect_url='/recommendations',
                metadata={
                    'signal_type': signal_type, 'count': count, 'symbols': symbols,
                    'date': str(today), 'items': items_data,
                },
                severity=SEVERITY_MAP.get(str(n_type), 'normal'),
            ))
        return alerts
